const root = $json && typeof $json === 'object' && !Array.isArray($json) ? $json : {};
const context = root.context && typeof root.context === 'object' && !Array.isArray(root.context) ? root.context : root;
const args = Array.isArray(context.command_args) ? context.command_args : [];
const argumentText = typeof context.argument_text === 'string' ? context.argument_text.trim() : '';
const explicit = typeof context.chapter_number === 'string' ? context.chapter_number : (Number.isInteger(context.chapter_number) && context.chapter_number > 0 ? String(context.chapter_number) : '');
const rawChapter = explicit || args.find((value) => /^\d+$/u.test(String(value ?? '').trim())) || argumentText.match(/\b(\d+)\b/u)?.[1] || '';
const chapterNumber = String(rawChapter).trim().padStart(3, '0');
const folderMap = context.workspace_folder_map && typeof context.workspace_folder_map === 'object' && !Array.isArray(context.workspace_folder_map) ? context.workspace_folder_map : {};
const chaptersFolderId = String(folderMap['02_Chapters'] ?? folderMap['chapters'] ?? context.chapters_folder_id ?? '').trim();
const workspaceFolderId = String(context.workspace_folder_id ?? context.root_folder_id ?? context.existing_root_folder_id ?? context.workspace_uuid ?? '').trim();
const errors = [];
if (!/^\d{3}$/u.test(chapterNumber)) errors.push('chapter_number must resolve to a three digit chapter id such as 001.');
if (!chaptersFolderId && !workspaceFolderId) errors.push('workspace folder id or 02_Chapters folder id is required.');
return [{ json: { ...root, chapter_number: chapterNumber, chapters_folder_id: chaptersFolderId, workspace_folder_id: workspaceFolderId, validation_errors: errors, is_valid: errors.length === 0 } }];

let prior = {};
try { prior = $('Parse Chapter Command').item.json; } catch { prior = {}; }
const found = Array.isArray($input.all()) ? $input.all().map((item) => item.json).find((item) => item && item.id) : null;
const chaptersFolderId = prior.chapters_folder_id || (found ? String(found.id) : '');
const errors = [...(prior.validation_errors ?? [])];
if (!chaptersFolderId) errors.push('02_Chapters folder was not found.');
return [{ json: { ...prior, chapters_folder_id: chaptersFolderId, is_valid: errors.length === 0, validation_errors: errors } }];

const prior = $('Resolve 02_Chapters').item.json;
const found = $input.all().map((item) => item.json).find((item) => item && item.id) ?? null;
return [{ json: { ...prior, chapter_folder_id: found ? String(found.id) : '', chapter_folder_existed: Boolean(found) } }];

let prior = {};
try { prior = $('Resolve Chapter Folder').item.json; } catch { prior = $json; }
const createdId = $json && $json.id ? String($json.id) : '';
const chapterFolderId = prior.chapter_folder_id || createdId;
const errors = [...(prior.validation_errors ?? [])];
if (prior.is_valid === true && !chapterFolderId) errors.push('chapter folder id is required.');
const isValid = errors.length === 0;
return [{ json: { route: 'chapter.completed', status: isValid ? 'ready' : 'error', is_valid: isValid, validation_errors: errors, chapter_number: prior.chapter_number, chapter_folder_id: chapterFolderId } }];
